(4004,10,'_elementor_controls_usage','a:15:{s:6:\"slides\";a:3:{s:5:\"count\";i:1;s:15:\"control_percent\";i:2;s:8:\"controls\";a:2:{s:7:\"content\";a:1:{s:14:\"section_slides\";a:2:{s:6:\"slides\";i:1;s:13:\"slides_height\";i:1;}}s:5:\"style\";a:2:{s:19:\"section_style_title\";a:3:{s:29:\"heading_typography_typography\";i:1;s:30:\"heading_typography_font_family\";i:1;s:30:\"heading_typography_font_weight\";i:1;}s:20:\"section_style_button\";a:3:{s:11:\"button_size\";i:1;s:23:\"button_background_color\";i:1;s:19:\"button_border_color\";i:1;}}}}s:9:\"container\";a:3:{s:5:\"count\";i:18;s:15:\"control_percent\";i:0;s:8:\"controls\";a:2:{s:6:\"layout\";a:1:{s:24:\"section_layout_container\";a:5:{s:14:\"flex_direction\";i:18;s:13:\"content_width\";i:5;s:5:\"width\";i:4;s:20:\"flex_justify_content\";i:2;s:8:\"flex_gap\";i:2;}}s:5:\"style\";a:2:{s:26:\"section_background_overlay\";a:1:{s:29:\"background_overlay_background\";i:3;}s:18:\"section_background\";a:1:{s:21:\"background_background\";i:1;}}}}s:5:\"video\";a:3:{s:5:\"count\";i:1;s:15:\"control_percent\";i:0;s:8:\"controls\";a:1:{s:7:\"content\";a:1:{s:13:\"section_video\";a:1:{s:11:\"youtube_url\";i:1;}}}}s:7:\"heading\";a:3:{s:5:\"count\";i:14;s:15:\"control_percent\";i:4;s:8:\"controls\";a:3:{s:7:\"content\";a:1:{s:13:\"section_title\";a:3:{s:5:\"title\";i:14;s:4:\"link\";i:6;s:11:\"header_size\";i:6;}}s:5:\"style\";a:1:{s:19:\"section_title_style\";a:7:{s:11:\"title_color\";i:14;s:21:\"typography_typography\";i:14;s:22:\"typography_font_family\";i:14;s:20:\"typography_font_size\";i:13;s:22:\"typography_font_weight\";i:14;s:5:\"align\";i:13;s:28:\"text_stroke_text_stroke_type\";i:3;}}s:8:\"advanced\";a:1:{s:14:\"_section_style\";a:3:{s:16:\"_flex_align_self\";i:3;s:11:\"_flex_order\";i:3;s:10:\"_flex_size\";i:3;}}}}s:11:\"text-editor\";a:3:{s:5:\"count\";i:8;s:15:\"control_percent\";i:2;s:8:\"controls\";a:3:{s:7:\"content\";a:1:{s:14:\"section_editor\";a:1:{s:6:\"editor\";i:8;}}s:5:\"style\";a:1:{s:13:\"section_style\";a:8:{s:10:\"text_color\";i:8;s:21:\"typography_typography\";i:8;s:22:\"typography_font_family\";i:8;s:22:\"typography_font_weight\";i:2;s:21:\"typography_font_style\";i:1;s:5:\"align\";i:8;s:22:\"typography_line_height\";i:7;s:20:\"typography_font_size\";i:7;}}s:8:\"advanced\";a:1:{s:15:\"section_effects\";a:1:{s:10:\"_animation\";i:1;}}}}s:7:\"reviews\";a:3:{s:5:\"count\";i:1;s:15:\"control_percent\";i:1;s:8:\"controls\";a:2:{s:7:\"content\";a:1:{s:14:\"section_slides\";a:3:{s:6:\"slides\";i:1;s:15:\"slides_per_view\";i:1;s:16:\"slides_to_scroll\";i:1;}}s:5:\"style\";a:1:{s:20:\"section_rating_style\";a:1:{s:10:\"star_style\";i:1;}}}}s:9:\"image-box\";a:3:{s:5:\"count\";i:7;s:15:\"control_percent\";i:3;s:8:\"controls\";a:2:{s:7:\"content\";a:1:{s:13:\"section_image\";a:3:{s:5:\"image\";i:7;s:10:\"title_text\";i:7;s:16:\"description_text\";i:7;}}s:5:\"style\";a:2:{s:17:\"section_style_box\";a:2:{s:11:\"image_space\";i:7;s:18:\"title_bottom_space\";i:7;}s:21:\"section_style_content\";a:6:{s:11:\"title_color\";i:7;s:17:\"description_color\";i:7;s:33:\"description_typography_typography\";i:7;s:34:\"description_typography_font_family\";i:7;s:32:\"description_typography_font_size\";i:7;s:34:\"description_typography_font_weight\";i:7;}}}}s:6:\"button\";a:3:{s:5:\"count\";i:13;s:15:\"control_percent\";i:4;s:8:\"controls\";a:3:{s:7:\"content\";a:1:{s:14:\"section_button\";a:2:{s:4:\"text\";i:13;s:4:\"link\";i:13;}}s:5:\"style\";a:1:{s:13:\"section_style\";a:13:{s:5:\"align\";i:13;s:21:\"typography_typography\";i:13;s:22:\"typography_font_family\";i:13;s:20:\"typography_font_size\";i:13;s:22:\"typography_font_weight\";i:13;s:17:\"button_text_color\";i:13;s:16:\"background_color\";i:13;s:25:\"button_hover_border_color\";i:13;s:13:\"border_border\";i:13;s:12:\"border_width\";i:13;s:12:\"border_color\";i:13;s:13:\"border_radius\";i:13;s:12:\"text_padding\";i:13;}}s:8:\"advanced\";a:1:{s:14:\"_section_style\";a:3:{s:16:\"_flex_align_self\";i:2;s:7:\"_margin\";i:1;s:8:\"_p